package app.officinalibri;
import org.json.*;import java.io.*;import java.util.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;
/** Same typed canonical encoding as packages/journey-content.mjs. */
public final class JourneyContent {
 private static String hex(byte[] bytes){StringBuilder b=new StringBuilder();for(byte n:bytes)b.append(String.format(Locale.ROOT,"%02x",n&255));return b.toString();}
 static String canonical(Object v)throws Exception {if(v==null||v==JSONObject.NULL)return "n";if(v instanceof String)return "s"+hex(((String)v).getBytes(StandardCharsets.UTF_8))+";";if(v instanceof Boolean)return (Boolean)v?"t":"f";if(v instanceof Number)return "d"+String.format(Locale.ROOT,"%016x",Double.doubleToLongBits(((Number)v).doubleValue()));StringBuilder b=new StringBuilder();if(v instanceof JSONArray){b.append('[');JSONArray a=(JSONArray)v;for(int i=0;i<a.length();i++)b.append(canonical(a.get(i)));return b.append(']').toString();}JSONObject o=(JSONObject)v;b.append('{');List<String> keys=new ArrayList<>();o.keys().forEachRemaining(keys::add);Collections.sort(keys);for(String k:keys)b.append(canonical(k)).append(canonical(o.get(k)));return b.append('}').toString();}
 public static String digest(File root,JSONObject journey)throws Exception {JSONObject p=MobileStore.json(new File(root,"manifest.json"));p.remove("revision");p.remove("updatedAt");p.remove("status");Set<String> used=new HashSet<>();JSONArray pages=p.getJSONArray("pages");for(int i=0;i<pages.length();i++){JSONArray nodes=pages.getJSONObject(i).getJSONArray("nodes");for(int j=0;j<nodes.length();j++)if("image".equals(nodes.getJSONObject(j).getString("type")))used.add(nodes.getJSONObject(j).getString("asset"));}JSONObject assets=p.getJSONObject("assets"),selected=new JSONObject();for(String key:used)selected.put(key,assets.get(key));p.put("assets",selected);File nf=new File(root,"romanzo.json");JSONObject n=nf.isFile()?MobileStore.json(nf):null;if(n!=null){n.remove("revision");n.remove("imports");}JSONObject brief=new JSONObject();JSONArray sources=new JSONArray();if(journey!=null){JSONObject source=journey.getJSONObject("brief");Iterator<String> keys=source.keys();while(keys.hasNext()){String k=keys.next();Object v=source.get(k);if(!"".equals(v)&&!(v instanceof JSONArray&&((JSONArray)v).length()==0))brief.put(k,v);}JSONArray refs=journey.getJSONArray("sources");for(int i=0;i<refs.length();i++){JSONObject r=refs.getJSONObject(i);sources.put(new JSONObject().put("label",r.getString("label")).put("reference",r.getString("reference")).put("notes",r.getString("notes")));}}JSONObject source=new JSONObject().put("project",p).put("novel",n==null?JSONObject.NULL:n).put("brief",brief).put("sources",sources);return hex(MessageDigest.getInstance("SHA-256").digest(canonical(source).getBytes(StandardCharsets.UTF_8)));}
}
